let contentInfo=null;
function validVideo(v){ return v&&typeof v.id==='string'&&typeof v.title==='string'&&v.source&&(v.source.type==='youtube'&&/^[A-Za-z0-9_-]{11}$/.test(v.source.id)||v.source.type==='file'&&typeof v.source.url==='string')&&Array.isArray(v.steps||[]); }
async function ladeJson(url){ try{ const r=await fetch(url,{cache:'no-store'}); if(!r.ok) return null; const j=await r.json(); return j&&Array.isArray(j.videos)?j:null; }catch(e){ return null; } }
async function loadContentFile(){
  if(!/^https?:/.test(location.protocol)) return;
  // Familie: zuerst alle Schulvideos (gleiche Schritte und Stopps wie in der Schule), dazu die Videos aus inhalte.json, die es nur dort gibt
  const [sch,fam]=await Promise.all([ladeJson(SCHULE?'schule.json':'schule/schule.json'),SCHULE?null:ladeJson('inhalte.json')]);
  if(!sch&&!fam) return;
  try{ const vs=(sch?sch.videos:[]).filter(validVideo), ids=new Set(vs.map(v=>v.id));
    if(fam) fam.videos.filter(validVideo).forEach(v=>{ if(!ids.has(v.id)){ vs.push(v); ids.add(v.id); return; } const sv=vs.find(x=>x.id===v.id); if(!sv.task&&v.task) sv.task=v.task; });
    ((sch&&sch.bereiche)||[]).forEach(a=>{ const ex=areaOf(a.id); if(ex) Object.assign(ex,a); else S.areas.push(a); });
    if(!SCHULE) THEMEN.forEach(t=>{ if(!areaOf(t.id)) S.areas.push(Object.assign({},t)); });
    vs.forEach(v=>{ v.quelle='datei'; const ex=videoOf(v.id); if(ex) Object.assign(ex,v); else S.videos.push(v); });
    [...((sch&&sch.geloescht)||[]),...((fam&&fam.geloescht)||[])].forEach(id=>{ S.videos=S.videos.filter(v=>v.id!==id); });
    const pos=new Map(vs.map((v,i)=>[v.id,i]));
    S.videos.sort((a,b)=>(pos.has(a.id)?pos.get(a.id):1e9)-(pos.has(b.id)?pos.get(b.id):1e9));
    S.areas.forEach(a=>{ if(!a.ding) a.ding=DING_BY_ID[a.id]||'kiste'; });
    contentInfo={n:vs.length,stand:(sch||fam).stand||''}; save();
  }catch(e){}
}
